INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26619$nota-0111$m26619$, $m26620$Training and Racing with a Power Meter.pdf$m26620$, $m26621$331$m26621$, $m26622$Rich Strauss and Patrick McCrann from Endurance Nation... give the triathlete a maximum 'budget' of 300 Training Stress Score (TSS) points for an Ironman-distance event... a 300-TSS Ironman is the maximum budget and puts you in the danger zone for not being able to run for the entire race. A more realistic TSS budget would be 280.$m26622$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26623$nota-0111$m26623$, $m26624$Training and Racing with a Power Meter.pdf$m26624$, $m26625$331$m26625$, $m26626$1. Figure out your TSS per hour. Simply divide the total TSS by the number of hours you will be racing (in our example, 280 divided by 6, which is 46.7). 2. Solve for the Intensity Factor. The TSS per hour... is equal to the square of the Intensity Factor times 100.$m26626$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26627$nota-0111$m26627$, $m26628$Training and Racing with a Power Meter.pdf$m26628$, $m26629$332$m26629$, $m26630$3. Calculate the average Normalized Power needed to maintain IF. Intensity Factor is equal to average Normalized Power divided by FTP: IF = Average NP ÷ FTP. Average NP is thus IF times FTP: Average NP = IF × FTP.$m26630$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26631$nota-0111$m26631$, $m26632$nota-0061$m26632$, $m26633$pre-requisito$m26633$, $m26634$usa as definições de IF e TSS (nota-0061 e correlatas) como ponto de partida do cálculo reverso$m26634$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26635$nota-0113$m26635$, $m26636$Training and Racing with a Power Meter.pdf$m26636$, $m26637$336$m26637$, $m26638$When riding uphill, in almost every situation, you can afford to produce more watts than you can in other parts of a triathlon or time trial. This is because you have more resistance to push against, and on the downhills, there isn't a big enough gear to allow you to produce the same level of force, no matter how hard you try.$m26638$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26639$nota-0113$m26639$, $m26640$Training and Racing with a Power Meter.pdf$m26640$, $m26641$337$m26641$, $m26642$your FTP is 215 watts, and on the longer uphills you ride right at your FTP, or above it on the shorter ones (106 percent, or 230 watts); on the downhills, you might be lucky to be able to produce 120 watts. That would be roughly 55 percent of your FTP, which is Level 1, or Active Recovery pace.$m26642$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26643$nota-0113$m26643$, $m26644$nota-0112$m26644$, $m26645$complementa$m26645$, $m26646$explica fisicamente por que as diretrizes de +5%/+10% em subidas (nota-0112) são sustentáveis apesar de excederem a potência-alvo$m26646$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26647$nota-0114$m26647$, $m26648$Training and Racing with a Power Meter.pdf$m26648$, $m26649$340$m26649$, $m26650$Dr. Stephen McGregor, co-author of this third edition... has developed the Running Training Stress Score (rTSS) to quantify the training stress from runs. Based on coauthor Andrew Coggan's work on TSS, rTSS has become a common method for measuring training stress in the running world. Instead of using the one-hour scale used in TSS for cycling, Stephen took the approach of trying to create a level playing field, so that 100 TSS points on the bike would be the same amount of training stress as 100 points on the run.$m26650$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26651$nota-0114$m26651$, $m26652$Training and Racing with a Power Meter.pdf$m26652$, $m26653$340$m26653$, $m26654$Since running has the additional musculoskeletal-structural risk that comes from pounding your feet on the pavement... an hour at functional threshold pace (FTp)... on the run would be more training stress than an hour on the bicycle, and consequently more recovery time would be required.$m26654$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26655$nota-0114$m26655$, $m26656$Training and Racing with a Power Meter.pdf$m26656$, $m26657$341$m26657$, $m26658$roughly 45 minutes of running at FTp, or a flat-out effort for 15 kilometers, would be equivalent to 1 hour at FTP on the bicycle.$m26658$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26659$nota-0114$m26659$, $m26660$nota-0062$m26660$, $m26661$complementa$m26661$, $m26662$estende a metodologia de TSS (nota-0062) para a corrida, mantendo a escala 100 pontos = 1h no limiar como equivalência de carga entre esportes$m26662$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26663$nota-0116$m26663$, $m26664$Training and Racing with a Power Meter.pdf$m26664$, $m26665$345$m26665$, $m26666$You cannot determine an Ironman triathlete's effort on the day of the event based on the 1-minute, 20-minute, and 120-minute values... the important thing to understand is what the athlete's TSB was, is, or will be on race day. A high positive TSB would mean the athlete is too fresh and has lost fitness, and a negative TSB could mean the athlete will be too fatigued to perform well.$m26666$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26667$nota-0116$m26667$, $m26668$Training and Racing with a Power Meter.pdf$m26668$, $m26669$345$m26669$, $m26670$Although it is possible to hold a peak for six to eight weeks, it's not advisable to attempt to do this; had she cranked out some big numbers two weeks before this event, we would be more confident that she would have hit her peak at just the right time.$m26670$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26671$nota-0116$m26671$, $m26672$Training and Racing with a Power Meter.pdf$m26672$, $m26673$346$m26673$, $m26674$Nearly all of her bests happened right after her normal rest weeks during a hard week of training.$m26674$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26675$nota-0116$m26675$, $m26676$nota-0085$m26676$, $m26677$pre-requisito$m26677$, $m26678$usa o TSB (nota-0085) como métrica primária de prontidão para provas longas, em vez dos picos de MMP por duração$m26678$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26679$nota-0116$m26679$, $m26680$nota-0094$m26680$, $m26681$complementa$m26681$, $m26682$reforça, num contexto de prova de ultraresistência, que o timing/trajetória do TSB importa mais que o valor absoluto de picos de potência$m26682$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26683$nota-0119$m26683$, $m26684$Training and Racing with a Power Meter.pdf$m26684$, $m26685$356$m26685$, $m26686$someone with an FTP of 340 watts can maybe put out 320 watts and rides at a speed of 32.5 mph in the tailwind, and a cyclist with an FTP of 320 watts can only put out about 300 watts in the tailwind and rides at an average speed of 32.1 mph. In a 40 km TT, this small speed difference for 20 km will result in the faster rider gaining only 17 seconds over the slower rider.$m26686$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26687$nota-0119$m26687$, $m26688$Training and Racing with a Power Meter.pdf$m26688$, $m26689$356$m26689$, $m26690$On the headwind section of the course, the rider with 340 watts can ride at 22 mph for the entire 20 km, and the rider with 320 watts averages only 20.5 mph for the same section. This gives the rider with 340 watts at FTP a 194-second advantage on that portion of the course.$m26690$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26691$nota-0119$m26691$, $m26692$nota-0021$m26692$, $m26693$pre-requisito$m26693$, $m26694$quantifica como o vento distorce a relação entre FTP (nota-0021) e velocidade/desempenho de prova$m26694$)
